'use client';
import {useState} from 'react';
import {signIn} from 'next-auth/react';
import {useRouter} from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import {ArrowLeft,ArrowRight,ShieldCheck,Loader2} from 'lucide-react';
import {Brand} from './city-shell';
import {DISTRICTS,HERO} from '@/lib/constants';
import {request,jsonBody} from '@/lib/client';
import {ErrorBox} from './city-ui';
export default function AuthForm({signup=false}:{signup?:boolean}){const router=useRouter();const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [imageFailed,setImageFailed]=useState(false);
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);const email=String(f.get('email')??'');const password=String(f.get('password')??'');try{if(signup)await request('/api/signup',{method:'POST',...jsonBody({name:f.get('name'),email,password,district:f.get('district'),role:f.get('role')})});const result=await signIn('credentials',{email,password,redirect:false});if(result?.error)throw new Error('E-posta veya şifre doğru değil.');router.replace('/');}catch(err){console.error(err);setError(err instanceof Error?err.message:'Giriş yapılamadı.');}finally{setBusy(false);}}
 return <div className="grid min-h-screen lg:grid-cols-2"><div className="relative hidden overflow-hidden bg-secondary text-secondary-foreground lg:flex lg:flex-col lg:justify-between lg:p-14">{!imageFailed&&<Image src={HERO} alt="İstanbul Boğaz Köprüsü ve şehir manzarası" fill unoptimized className="object-cover opacity-35" onError={()=>setImageFailed(true)}/>}<div className="absolute inset-0 bg-gradient-to-t from-secondary via-secondary/30 to-secondary/60"/><div className="relative"><Brand/></div><div className="relative mb-16 max-w-md"><p className="eyebrow mb-6 text-secondary-foreground/65">39 İLÇE. TEK İSTANBUL.</p><h1 className="text-5xl font-semibold leading-tight tracking-tight">Şehrin geleceğinde<br/>senin de izin olsun.</h1><p className="mt-6 text-base leading-relaxed text-secondary-foreground/70">Taleplerini ilet, başvurularını takip et ve mahallendeki gelişmelerden haberdar ol.</p></div><p className="relative text-xs text-secondary-foreground/50">İstanbul Akıllı Şehir · Vatandaş Hizmetleri</p></div><div className="flex items-center justify-center px-6 py-10"><div className="w-full max-w-md"><Link href="/" className="mb-10 inline-flex items-center gap-2 text-sm text-muted-foreground"><ArrowLeft size={16}/>Ana sayfaya dön</Link><div className="mb-9 lg:hidden"><Brand/></div><h2 className="page-title">{signup?'İstanbul için bir adım at.':'Tekrar hoş geldin.'}</h2><p className="mt-3 mb-7 text-sm text-muted-foreground">{signup?'Hesabını oluştur, şehrinle bağlantıda kal.':'Başvurularına ve şehir hizmetlerine ulaşmak için giriş yap.'}</p><ErrorBox message={error}/><form onSubmit={submit} className="space-y-4">{signup&&<label className="field">Ad soyad<input name="name" autoComplete="name" required minLength={2} maxLength={80} placeholder="Adınız ve soyadınız"/></label>}<label className="field">E-posta adresi<input name="email" type="email" autoComplete="email" required placeholder="E-posta adresiniz"/></label><label className="field">Şifre<input name="password" type="password" autoComplete={signup?'new-password':'current-password'} required minLength={signup?8:1} maxLength={128} placeholder={signup?'En az 8 karakter':'Şifrenizi girin'}/></label>{signup&&<div className="grid grid-cols-2 gap-4"><label className="field">İlçeniz<select name="district" defaultValue="Kadıköy">{DISTRICTS.map((d)=><option key={d}>{d}</option>)}</select></label><label className="field">Hesap türü<select name="role"><option value="CITIZEN">Vatandaş</option><option value="BUSINESS">İşletme</option><option value="TOURIST">Ziyaretçi</option></select></label></div>}{signup&&<p className="rounded-lg bg-muted p-3 text-[11px] leading-relaxed text-muted-foreground">Hesap bilgileriniz hizmet sunmak için saklanır. Başvurularınız ve fotoğraflarınız yalnızca size ve yetkili yöneticilere açıktır. Belediye yetkisi herkese açık kayıtla verilemez.</p>}<button disabled={busy} className="btn w-full !py-3">{busy?<Loader2 size={18} className="animate-spin"/>:<ArrowRight size={17}/>} {busy?'İşlem yapılıyor…':signup?'Hesap oluştur':'Giriş yap'}</button></form><p className="mt-6 text-center text-sm text-muted-foreground">{signup?'Zaten hesabın var mı?':'Henüz hesabın yok mu?'} <Link className="font-semibold text-primary" href={signup?'/login':'/signup'}>{signup?'Giriş yap':'Kayıt ol'}</Link></p><div className="mt-10 flex items-center justify-center gap-2 text-[11px] text-muted-foreground"><ShieldCheck size={16}/>Güvenli ve kişisel hizmet alanı</div></div></div></div>;
}
